<?php

/* @autogenerated */
declare(strict_types=1);

require_once __DIR__ . '/FormsTestCase.php';

use PHPUnit\Framework\Attributes\AllowMockObjectsWithoutExpectations;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\ChallengesState;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\StepResult;
use Civi\Lughauth\Features\OAuth\Authentication\Infrastructure\Driver\Html\Forms\UseMfaForm;
use Civi\Lughauth\Features\OAuth\Authentication\Application\AuthenticateUser;
use Civi\Lughauth\Features\OAuth\Theme\Application\DecorateHtml;
use Civi\Lughauth\Features\OAuth\Authentication\Infrastructure\Driver\Html\Services\HtmlSecurer;
use Civi\Lughauth\Features\OAuth\Authentication\Infrastructure\Driver\Html\Services\PublicMfa;
use Civi\Lughauth\Features\OAuth\User\Domain\PublicLoginAuthResponse;
use Civi\Lughauth\Shared\Infrastructure\Translation\MessageProvider;

/**
 * Unit tests for {@see UseMfaForm} step integration.
 */
#[AllowMockObjectsWithoutExpectations]
final class UseMfaFormStepUnitTest extends FormsTestCase
{
    public function testAuthenticateSkipsMfaWhenAlreadyVerified(): void
    {
        $input = $this->buildInput(['mfa_code' => '123456'], new ChallengesState(withMfa: true, username: 'user-1'));
        $authResponse = $this->createMock(PublicLoginAuthResponse::class);

        $authenticator = $this->createMock(AuthenticateUser::class);
        $authenticator->expects($this->once())
            ->method('preAuthenticate')
            ->willReturn($authResponse);

        $form = new UseMfaForm(
            $this->createMock(MessageProvider::class),
            $authenticator,
            $this->createMock(PublicMfa::class),
            $this->createMock(DecorateHtml::class),
            $this->createMock(HtmlSecurer::class)
        );

        $result = $form->authenticate($input);

        $this->assertInstanceOf(StepResult::class, $result);
        $this->assertSame(StepResult::TYPE_PROCEED, $result->type);
        $this->assertSame($authResponse, $result->authResponse);
        $this->assertSame($input->challenges, $result->challenges);
    }

    public static function languages(): array
    {
        return [
            'ui_locales chooses English' => [['ui_locales' => 'en'], 'es-ES,es;q=0.9', 'en', 'Second factor'],
            'ui_locales chooses Spanish' => [['ui_locales' => 'es'], 'en-US', 'es', 'Segundo factor'],
            'Accept-Language is the fallback' => [['ui_locales' => 'fr'], 'en-GB,en;q=0.8', 'en', 'Second factor'],
            'default without preference' => [[], '', 'es', 'Segundo factor'],
        ];
    }

    #[\PHPUnit\Framework\Attributes\DataProvider('languages')]
    public function testRenderUsesTheNegotiatedLanguage(array $query, string $acceptLanguage, string $locale, string $title): void
    {
        $page = null;
        $pageLocale = null;
        $decorator = $this->createMock(DecorateHtml::class);
        $decorator->method('getFullPage')->willReturnCallback(
            function ($request, string $pageTitle, string $content, string $usedLocale) use (&$page, &$pageLocale): string {
                [$page, $pageLocale] = [$content, $usedLocale];
                return $content;
            }
        );
        $form = new UseMfaForm(
            new MessageProvider(new \Civi\Lughauth\Shared\AppConfig()),
            $this->createMock(AuthenticateUser::class),
            $this->createMock(PublicMfa::class),
            $decorator,
            $this->createMock(HtmlSecurer::class)
        );

        $form->render($this->buildInput([], new ChallengesState(), $query, $acceptLanguage), new \Slim\Psr7\Response(), null);

        $this->assertSame($locale, $pageLocale);
        $this->assertStringContainsString("<h1>{$title}</h1>", (string) $page);
    }
}
